  const raw = intPart + fracPart;
  const lz = raw.match(/^0*/)[0].length;
  const sig = raw.slice(lz); // significant digits (may keep trailing zeros)
  // Decimal exponent E: value = sig[0].sig[1...] x 10^E
  const E = e + intPart.length - 1 - lz;

  let out;
  if (E < -4 || E >= 16) {
    const d = sig[0];
    const rest = sig.slice(1).replace(/0+$/, '');
    const m = rest ? `${d}.${rest}` : d;
    const sign = E >= 0 ? '+' : '-';
    const expAbs = String(Math.abs(E)).padStart(2, '0');
    out = `${m}e${sign}${expAbs}`;
  } else if (E >= sig.length - 1) {
    out = sig + '0'.repeat(E - sig.length + 1) + '.0';
  } else if (E >= 0) {
    out = `${sig.slice(0, E + 1)}.${sig.slice(E + 1)}`;
  } else {
    out = `0.${'0'.repeat(-E - 1)}${sig}`;
  }
  return neg ? `-${out}` : out;
}

// Reproduce CPython's repr() for a string: single quotes preferred,
// double quotes when the string contains a single quote but no double.
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += `\\${quote}`;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 32 || code === 127) {
      out += `\\x${code.toString(16).padStart(2, '0')}`;
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// Equivalent of Python's repr()/str() for the value kinds this program prints.
export function pyRepr(v) {
  if (v === null) return 'None';
  if (v === true) return 'True';
  if (v === false) return 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return String(v);
  if (v instanceof PyFloat) return pyFloatRepr(v.value);
  if (typeof v === 'string') return pyStrRepr(v);
  if (Array.isArray(v)) return `[${v.map(pyRepr).join(', ')}]`;
  throw new TypeError(`unsupported type for repr: ${typeof v}`);
}

// Minimal reimplementation of Python's eval() for literal expressions:
// lists, tuples, numbers (int/float), strings, True/False/None, unary +/-.

import { PyFloat } from './pytypes.mjs';

class Parser {
  constructor(src) {
    this.src = src;
    this.pos = 0;
  }

  error(msg) {
    throw new SyntaxError(msg);
  }

  skipWs() {
    while (this.pos < this.src.length && /\s/.test(this.src[this.pos])) this.pos++;
  }

  atEnd() {
    return this.pos >= this.src.length;
  }

  peek() {
    return this.src[this.pos];
  }

  parseValue() {
    this.skipWs();
    if (this.atEnd()) this.error('unexpected EOF while parsing');
    const ch = this.peek();
    if (ch === '[') return this.parseSeq('[', ']');
    if (ch === '(') return this.parseSeq('(', ')');
    if (ch === "'" || ch === '"') return this.parseString();
    if (ch === '-' || ch === '+') {
      this.pos++;
      return this.applyUnary(ch, this.parseValue());
    }
    if (/[0-9.]/.test(ch)) return this.parseNumber();
    if (/[A-Za-z_]/.test(ch)) {
      const name = this.parseName();
      if (name === 'True') return true;
      if (name === 'False') return false;
      if (name === 'None') return null;
      this.error(`invalid syntax near '${name}'`);
    }
    this.error(`unexpected character '${ch}'`);
  }

  parseSeq(open, close) {
    this.pos++; // consume open
    const items = [];
    this.skipWs();
    if (this.peek() === close) {
      this.pos++;
      return items;
    }
    for (;;) {
      items.push(this.parseValue());
      this.skipWs();
      if (this.atEnd()) this.error(`'${open}' was never closed`);
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === close) {
          this.pos++; // trailing comma
          return items;
        }
        continue;
      }
      if (ch === close) {
        this.pos++;
        return items;
      }
      this.error(`expected ',' or '${close}'`);
    }
  }

  parseNumber() {
    const re = /(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?/y;
    re.lastIndex = this.pos;
    const m = re.exec(this.src);
    if (!m) this.error('invalid numeric literal');
    this.pos += m[0].length;
    const text = m[0];
    if (/[.eE]/.test(text)) return new PyFloat(Number(text));
    return BigInt(text);
  }

  parseString() {
    const quote = this.src[this.pos++];
    let out = '';
    for (;;) {
      if (this.atEnd()) this.error('unterminated string literal');
      const ch = this.src[this.pos++];
      if (ch === quote) return out;
      if (ch !== '\\') {
        out += ch;
        continue;
      }
      if (this.atEnd()) this.error('unterminated string literal');
      const esc = this.src[this.pos++];
      switch (esc) {
        case 'n': out += '\n'; break;
        case 't': out += '\t'; break;
        case 'r': out += '\r'; break;
        case 'a': out += '\x07'; break;
        case 'b': out += '\b'; break;
        case 'f': out += '\f'; break;
        case 'v': out += '\v'; break;
        case '0': out += '\0'; break;
        case '\\': out += '\\'; break;
        case "'": out += "'"; break;
        case '"': out += '"'; break;
        case 'x': {
          const hex = this.src.slice(this.pos, this.pos + 2);
          if (!/^[0-9a-fA-F]{2}$/.test(hex)) this.error('invalid \\x escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 2;
          break;
        }
        case 'u': {
          const hex = this.src.slice(this.pos, this.pos + 4);
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.error('invalid \\u escape');
          out += String.fromCharCode(parseInt(hex, 16));
          this.pos += 4;
          break;
        }
        default:
          out += `\\${esc}`; // Python keeps unknown escapes verbatim
      }
    }
  }

  parseName() {
    const re = /[A-Za-z_][A-Za-z0-9_]*/y;
    re.lastIndex = this.pos;
    const m = re.exec(this.src);
    this.pos += m[0].length;
    return m[0];
  }

  applyUnary(op, v) {
    const sign = op === '-' ? -1 : 1;
    if (typeof v === 'bigint') return sign === -1 ? -v : v;
    if (v instanceof PyFloat) return new PyFloat(sign * v.value);
    if (v === true) return BigInt(sign);
    if (v === false) return 0n;
    this.error(`bad operand type for unary '${op}'`);
  }
}

export function pyEval(src) {
  const p = new Parser(src);
  const value = p.parseValue();
  p.skipWs();
  if (!p.atEnd()) p.error(`unexpected trailing characters at position ${p.pos}`);
  return value;
}

// Reimplementation of the boltons.iterutils helpers used by the script.
// Arrays stand in for Python lists/tuples; strings and scalars are atomic.

export function* flatten(iterable) {
  for (const item of iterable) {
    if (Array.isArray(item)) {
      yield* flatten(item);
    } else {
      yield item;
    }
  }
}

export function* chunked(iterable, chunkSize) {
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new TypeError('chunk_size expected a positive integer');
  }
  const items = Array.isArray(iterable) ? iterable : Array.from(iterable);
  for (let i = 0; i < items.length; i += chunkSize) {
    yield items.slice(i, i + chunkSize);
  }
}

// Minimal argparse clone covering exactly the original parser:
//   parser.add_argument('--a', type=str, required=True, help='Nested list structure')

export function parseArgs(argv, prog) {
  const usage = `usage: ${prog} [-h] --a A`;
  const fail = (msg) => {
    console.error(usage);
    console.error(`${prog}: error: ${msg}`);
    process.exit(2);
  };

  let a;
  const extras = [];
  const rest = [...argv];
  while (rest.length) {
    const tok = rest.shift();
    if (tok === '-h' || tok === '--help') {
      console.log(usage);
      console.log('');
      console.log('options:');
      console.log('  -h, --help  show this help message and exit');
      console.log('  --a A       Nested list structure');
      process.exit(0);
    } else if (tok === '--a') {
      if (!rest.length) fail('argument --a: expected one argument');
      a = rest.shift();
    } else if (tok.startsWith('--a=')) {
      a = tok.slice('--a='.length);
    } else {
      extras.push(tok);
    }
  }
  if (extras.length) fail(`unrecognized arguments: ${extras.join(' ')}`);
  if (a === undefined) fail('the following arguments are required: --a');
  return { a };
}

