// Equivalent of Python's `x * 2` for every type the input can contain.
function mul2(x) {
  if (typeof x === 'bigint') return x * 2n;
  if (x instanceof PyFloat) return new PyFloat(x.value * 2);
  if (typeof x === 'string') return x + x;
  if (x === true) return 2n; // True * 2 == 2
  if (x === false) return 0n; // False * 2 == 0
  if (x === null) {
    throw new TypeError("unsupported operand type(s) for *: 'NoneType' and 'int'");
  }
  throw new TypeError(`unsupported operand type(s) for *: '${typeof x}' and 'int'`);
}

function main() {
  const nested = pyEval(args.a);

  const print = (v) => console.log(pyRepr(v));

  const result1 = Array.from(flatten(nested)); // 展平嵌套列表
  print(result1);
  const result2 = Array.from(chunked(result1, 2)); // 对展平结果分块
  print(result2);
  const result3 = Array.from(chunked(result1, 3)); // 按3分块
  print(result3);
  const nested2 = result2.map((chunk) => chunk.map(mul2)); // 处理分块
  const result4 = Array.from(flatten(nested2)); // 再次展平
  print(result4);
  const result5 = Array.from(chunked(result4, 4)); // 最终分块
  print(result5);
}

try {
  main();
} catch (err) {
  // Python prints the traceback to stderr and exits with code 1.
  console.error(`${err.name}: ${err.message}`);
  process.exit(1);
}
